INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('79j36cz2gfdx3yxv3279j32newizjh7y', '2026-Q3', 'Set/2026 (T3)', '2026-09-21T09:46'::timestamptz, 'Jonathas Alberto Ribeiro Abdou', 'jonathas alberto ribeiro abdou', 'PHARUS', 'João Aliceda', 5.0, 'Detrator', 5.0, NULL, NULL, NULL, NULL, NULL, 'Em progresso, mas com dúvidas', 'Entendi o método, mas ainda não implementei o suficiente', 'Eu achava que as interessões com o engenheiro patrimonial serial mais ricas e detalhadas. Parecia que ele seguia um roteiro e a entrega na explicação e know how do engenheiro não ficava tão explicita pra mim. Ultima sessão parecia que eles estava com pressa (foi só 30min de conversa). Pela valor cobrado, esperava uma personalização melhor', 'Personalizar melhor as entregas nas primeiras conversas. Achava que as janelas de investimentos fossem mais frequentes.', NULL, 'Resultado comprovado. O Gráfico que vi hoje (reunião de fluxo de caixa) de ganho de capital, dava um retorno de 1,08% do CDI. Pra ter esse ganho deixo no Tesouro Selic com 100% do CDI e paro de pagar as parcelas do Pharus que ganharia mais.', 'Insights interessantes. Acho que daria para ser uma boa experiencia. Mas hoje não tenho mais certeza de que fiz um bom negócio investir 20K no programa.', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', '79j36cz2gfdx3yxv3279j32newizjh7y', 'cadastro 2026-T3 (respondente) (0 dias)', 'base mecanismos') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, c